'use client';

import { useState } from 'react';

const PropertyDetail = () => {
  const [checkIn, setCheckIn] = useState('');
  const [checkOut, setCheckOut] = useState('');
  const [guests, setGuests] = useState(1);
  const [nights, setNights] = useState(0);

  const images = [
    'https://a0.muscache.com/im/pictures/hosting/Hosting-1158357014875094502/original/a0638242-53de-462a-b6d9-bac98863f931.jpeg?im_w=960',
    'https://a0.muscache.com/im/pictures/hosting/Hosting-1158357014875094502/original/5a9b17fc-0fe1-474f-9be3-fed3c4913d13.jpeg?im_w=720',
    'https://a0.muscache.com/im/pictures/hosting/Hosting-1158357014875094502/original/f552426b-52af-40ba-bb08-214eeb14937a.jpeg?im_w=720',
    'https://a0.muscache.com/im/pictures/hosting/Hosting-1158357014875094502/original/1b375715-f77e-47f0-bd4f-b5bfbc73db53.jpeg?im_w=720',
    'https://a0.muscache.com/im/pictures/hosting/Hosting-1158357014875094502/original/719ce935-cb8d-4638-b107-ca0625de1323.jpeg?im_w=720'
  ];

  const calculateNights = () => {
    if (checkIn && checkOut) {
      const start = new Date(checkIn);
      const end = new Date(checkOut);
      const diff = Math.ceil((end.getTime() - start.getTime()) / (1000 * 3600 * 24));
      setNights(diff);
    }
  };

  const handleReserve = () => {
    if (!checkIn || !checkOut) {
      alert('Please select check-in and check-out dates');
      return;
    }
    alert(`Reservation confirmed! Total: ₹${(5143 * nights) + 200 + 3659}`);
  };

  return (
    <div className="max-w-5xl mx-auto px-4 py-8">
      {/* Image Gallery */}
      <div className="grid grid-cols-2 gap-2 rounded-xl overflow-hidden shadow-md">
        {/* First large image */}
        <img
          src={images[0]}
          alt="Property"
          className="col-span-1 row-span-2 w-full h-[400px] object-cover rounded-l-lg"
        />

        {/* Remaining small images */}
        <div className="grid grid-cols-2 gap-2">
          {images.slice(1, 5).map((img, index) => (
            <img
              key={index}
              src={img}
              alt={`Image ${index + 2}`}
              className="w-full h-[190px] object-cover rounded-lg cursor-pointer hover:opacity-90 transition"
            />
          ))}
        </div>
      </div>

      {/* Property Info */}
      <div className="mt-6">
        <h1 className="text-3xl font-semibold">$1,150,000</h1>
        <p className="text-gray-500">6005 Mimosa Lane, Dallas, TX 75230</p>
        <div className="flex gap-4 mt-2 text-gray-500">
          <span>3 Beds</span>
          <span>3 Baths</span>
          <span>2,061 Sq. Ft.</span>
        </div>
      </div>

      {/* Reservation Card */}
      <div className="mt-8 bg-white shadow-md rounded-xl p-6 border border-gray-200">
        {/* Pricing */}
        <div className="flex items-center justify-between">
          <div className="flex gap-2 items-center">
            <span className="text-gray-400 line-through">₹7000</span>
            <span className="text-xl font-bold text-gray-800">₹5143</span>
            <span className="text-gray-500 text-sm">/ night</span>
          </div>
        </div>

        {/* Date Inputs */}
        <div className="flex gap-4 mt-4">
          <input
            type="date"
            value={checkIn}
            onChange={(e) => {
              setCheckIn(e.target.value);
              calculateNights();
            }}
            className="w-1/2 border border-gray-300 rounded-lg px-4 py-2 focus:outline-none focus:ring-2 focus:ring-blue-400"
            placeholder="Check-in"
          />
          <input
            type="date"
            value={checkOut}
            onChange={(e) => {
              setCheckOut(e.target.value);
              calculateNights();
            }}
            className="w-1/2 border border-gray-300 rounded-lg px-4 py-2 focus:outline-none focus:ring-2 focus:ring-blue-400"
            placeholder="Check-out"
          />
        </div>

        {/* Guests Selection */}
        <div className="mt-4">
          <select
            value={guests}
            onChange={(e) => setGuests(parseInt(e.target.value))}
            className="w-full border border-gray-300 rounded-lg px-4 py-2 focus:outline-none focus:ring-2 focus:ring-blue-400"
          >
            {[...Array(10)].map((_, i) => (
              <option key={i + 1} value={i + 1}>
                {i + 1} {i === 0 ? 'guest' : 'guests'}
              </option>
            ))}
          </select>
        </div>

        {/* Reserve Button */}
        <button
          onClick={handleReserve}
          className="w-full bg-gradient-to-r from-red-500 to-red-600 text-white font-semibold py-3 rounded-lg mt-4 hover:from-red-600 hover:to-red-700 transition duration-200"
        >
          Reserve
        </button>

        {/* Price Breakdown */}
        {nights > 0 && (
          <div className="mt-6 text-gray-700">
            <div className="flex justify-between mb-2">
              <span>₹5143 x {nights} nights</span>
              <span>₹{5143 * nights}</span>
            </div>
            <div className="flex justify-between mb-2">
              <span>Cleaning fee</span>
              <span>₹200</span>
            </div>
            <div className="flex justify-between mb-2">
              <span>Service fee</span>
              <span>₹3659</span>
            </div>
            <hr className="my-2 border-t border-gray-300" />
            <div className="flex justify-between font-semibold">
              <span>Total before taxes</span>
              <span>₹{(5143 * nights) + 200 + 3659}</span>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default PropertyDetail;
